func runPrefix(prefix, executable string, args ...string) error {
	fmt.Printf("%s running: %s %s\n", prefix, executable, strings.Join(args, " "))

	cmd := Execer(executable, args...)

	stdout, err := cmd.StdoutPipe()

	if err != nil {
		return err
	}

	stderr, err := cmd.StderrPipe()

	if err != nil {
		return err
	}

	err = cmd.Start()

