// ExpectPeerReleases registers expectations on a MockTransport to release peers through the ReleasePeer function
func ExpectPeerReleases(
	transport *MockTransport,
	peerStrs []string,
	err error,
) {
	for _, peerStr := range peerStrs {
		transport.EXPECT().ReleasePeer(PeerIdentifierMatcher(peerStr), gomock.Any()).Return(err)
	}
}

File: transport/http/outbound.go  Lines: 95-110
// NewSingleOutbound creates an outbound from a single URL (a bare host:port is
// not sufficient).
// This form defers to the underlying HTTP agent's peer selection and load
// balancing, using DNS.
func (t *Transport) NewSingleOutbound(URL string, opts ...OutboundOption) *Outbound {
	parsedURL, err := url.Parse(URL)
	if err != nil {
		panic(err.Error())
	}
	o := t.NewOutbound(peerchooser.NewSingle(hostport.PeerIdentifier(parsedURL.Host), t))
	o.setURLTemplate(URL)
	for _, opt := range opts {
		opt(o)
	}
	return o
}

