+	fullKey, err := types.NewTuple(nr.Format(), vals...)
+	if err != nil {
+		return types.Tuple{}, types.Tuple{}, err
+	}
+	partialKey, err := types.NewTuple(nr.Format(), vals[:idx.Count()*2]...)
+	if err != nil {
+		return types.Tuple{}, types.Tuple{}, err
+	}
+	return fullKey, partialKey, nil
+}

