	if err != nil {
		return types.Tuple{}, types.Tuple{}, err
	}
	partialKey, err := types.NewTuple(nbf, vals[:idx.Count()*2]...)
	if err != nil {
		return types.Tuple{}, types.Tuple{}, err
	}
	return fullKey, partialKey, nil
}

