func commands(state *core.BuildState, labels []core.BuildLabel, run bool) []string {
	if run {
		if len(labels) > 1 {
			return []string{"run", "parallel"}
		}
		return []string{"run"}
	}
	for _, label := range labels {
		if state.Graph.TargetOrDie(label).IsTest {
			return []string{"test"}
		}
	}
	return []string{"build"}
}

