func checkMinMaxValue(a *AttributeExpr, example interface{}) bool {
	if !hasMinMaxValidation(a) {
		return true
	}
	if min := a.Validation.Minimum; min != nil {
		if v, ok := example.(int); ok && float64(v) < *min {
			return false
		} else if v, ok := example.(float64); ok && v < *min {
			return false
		}
