+func parseHealthHeaders(d *caddyfile.Dispenser) (http.Header, error) {
+	healthHeaders := http.Header{}
+	for d.Next() {
+		for d.NextBlock(0) {
+			key := d.Val()
+			values := d.RemainingArgs()
+			if len(values) == 0 {
