// Shutdown waits for all active calls to Add to finish, then
// returns. After Shutdown is called, all calls to Add fail.
func (b *Batcher) Shutdown() {
	b.mu.Lock()
	b.shutdown = true
	b.mu.Unlock()
	b.wg.Wait()
}

