		ProviderID: proposal.ProviderID,
	}, signer)
	if err != nil {
		return err
	}

	err = mApi.doRequest(req)

	if err == nil {
		log.Info(mysteriumAPILogPrefix, "Proposal unregistered for node: ", proposal.ProviderID)
	}

	return err
}

