File: network/address.go  Lines: 148-161
// Public returns true if the address is a public and valid one
// or false otherwise.
// Specifically it checks if it is a private address by checking
// 192.168.**,10.***,127.***,172.16-31.**,169.254.**
func (a Address) Public() bool {
	private, err := regexp.MatchString("(^127\\.)|(^10\\.)|"+
		"(^172\\.1[6-9]\\.)|(^172\\.2[0-9]\\.)|"+
		"(^172\\.3[0-1]\\.)|(^192\\.168\\.)|(^169\\.254)|"+
		"(^\\[::\\])", a.NetworkAddress())
	if err != nil {
		return false
	}
	return !private && a.Valid()
}

File: sda/conode.go  Lines: 45-63
// NewConode returns a fresh Host with a given Router.
func NewConode(r *network.Router, pkey abstract.Scalar) *Conode {
	c := &Conode{
		private:              pkey,
		statusReporterStruct: newStatusReporterStruct(),
		Router:               r,
		protocols:            newProtocolStorage(),
		started:              time.Now(),
	}
	c.overlay = NewOverlay(c)
	c.websocket = NewWebSocket(r.ServerIdentity)
	c.serviceManager = newServiceManager(c, c.overlay)
	c.statusReporterStruct.RegisterStatusReporter("Status", c)
	for name, inst := range protocols.instantiators {
		log.Lvl4("Registering global protocol", name)
		c.ProtocolRegister(name, inst)
	}
	return c
}

